  HUBSPOT_FOLDER_ID: 'PASTE_HUBSPOT_FOLDER_ID_HERE',
  STRIPE_FOLDER_ID:  'PASTE_STRIPE_FOLDER_ID_HERE',

  // Sheet tab names
